/*
 * A192581  Monotonic ordering of set S generated by these rules: if x and y
 *          are in S and xy+1 is a prime, then xy+1 is in S, and 2 and 4 are
 *          in S.
 * https://oeis.org/A192581
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, fini, full
 * Formula:   not stated
 * Range:     u8 n <= 7, u16 n <= 7, u32 n <= 7, u64 n <= 7, u128 n <= 7,
 *            big any n
 * Helpers:   is_prime_big, seq_alloc, seq_free
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A192581 – monotonic ordering of the set S:
   2 and 4 are in S; whenever x,y∈S and xy+1 is prime, xy+1 is added to S.
   a(n) is the n‑th smallest element of S (offset 1). */
/* The implementation keeps S sorted and uses a binary min‑heap to
   generate the next prime candidate in ascending order.  All arithmetic
   involving potential overflow is performed with unsigned __int128
   when seq_t is an integral type of 64 bits or less.  For arbitrary‑
   precision seq_t the big integer operators are used directly.  */

#include <stdint.h>
#include <stdbool.h>
#include <limits.h>
#include <stddef.h>
#include "../utils/is_prime_big.h"
#include "../utils/seq_alloc.h"
#include "../utils/seq_free.h"

/* ------------------------------------------------------------------ */
/* min‑heap helpers                                                    */
/* ------------------------------------------------------------------ */
static seq_t *heap = NULL;      /* array of heap elements          */
static size_t heap_sz = 0;      /* number of elements in the heap  */
static size_t heap_cap = 0;     /* allocated capacity              */

static void heap_grow(void)
{
    size_t new_cap = heap_cap ? heap_cap * 2 : 16;
    seq_t *tmp = seq_alloc(new_cap);
    for (size_t i = 0; i < heap_sz; ++i) tmp[i] = heap[i];
    if (heap) seq_free(heap);
    heap = tmp;
    heap_cap = new_cap;
}

static void heap_push(seq_t val)
{
    if (heap_sz >= heap_cap) heap_grow();
    size_t i = heap_sz++;
    heap[i] = val;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap[p] <= heap[i]) break;
        seq_t tmp = heap[p];
        heap[p] = heap[i];
        heap[i] = tmp;
        i = p;
    }
}

static seq_t heap_pop(void)
{
    seq_t min = heap[0];
    heap[0] = heap[--heap_sz];
    size_t i = 0;
    while (1) {
        size_t l = (i << 1) + 1;
        size_t r = l + 1;
        size_t smallest = i;
        if (l < heap_sz && heap[l] < heap[smallest]) smallest = l;
        if (r < heap_sz && heap[r] < heap[smallest]) smallest = r;
        if (smallest == i) break;
        seq_t tmp = heap[i];
        heap[i] = heap[smallest];
        heap[smallest] = tmp;
        i = smallest;
    }
    return min;
}

/* ------------------------------------------------------------------ */
/* sequence storage                                                    */
/* ------------------------------------------------------------------ */
static seq_t *S = NULL;        /* sorted sequence elements         */
static size_t sz = 0;          /* number of elements stored        */
static size_t S_cap = 0;       /* allocated capacity               */

static void S_grow(void)
{
    size_t new_cap = S_cap ? S_cap * 2 : 16;
    seq_t *tmp = seq_alloc(new_cap);
    for (size_t i = 0; i < sz; ++i) tmp[i] = S[i];
    if (S) seq_free(S);
    S = tmp;
    S_cap = new_cap;
}

/* ------------------------------------------------------------------ */
/* one‑time initialization                                            */
/* ------------------------------------------------------------------ */
static uint64_t seq_t_max = 0;  /* maximum representable value for seq_t */
static bool initialized = false;

static void init_sequence(void)
{
    if (initialized) return;
    initialized = true;

    /* set the maximum value that fits in seq_t for integral types */
    if (sizeof(seq_t) <= 8) {
        if (sizeof(seq_t) == 8)
            seq_t_max = UINT64_MAX;
        else
            seq_t_max = ((uint64_t)1 << (sizeof(seq_t) * 8)) - 1;
    } else {
        /* For arbitrary‑precision seq_t, set to a very large value
           that will never be exceeded by the products we build.  */
        seq_t_max = UINT64_MAX;
    }

    /* seed the sequence with 2 and 4 */
    S_cap = 16;
    S = seq_alloc(S_cap);
    S[0] = (seq_t)2;
    S[1] = (seq_t)4;
    sz = 2;

    /* initialise the heap with all initial candidates from {2,4} */
    for (size_t i = 0; i < sz; ++i) {
        for (size_t j = i; j < sz; ++j) {
            seq_t x = S[i], y = S[j];
            seq_t cand;
            if (sizeof(seq_t) <= 8) {
                unsigned __int128 prod = (unsigned __int128)(uint64_t)x *
                                        (unsigned __int128)(uint64_t)y + 1;
                if (prod > (unsigned __int128)seq_t_max) continue;
                cand = (seq_t)prod;
            } else {
                cand = x * y + (seq_t)1;
            }
            if (!is_prime_big(cand)) continue;
            heap_push(cand);
        }
    }
}

/* ------------------------------------------------------------------ */
/* public interface                                                   */
/* ------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;  /* undefined for offset 1 */

    init_sequence();

    /* return already computed value */
    if (n <= sz) return S[n - 1];

    /* generate until the requested index is reached */
    while (sz < (size_t)n) {
        seq_t next = heap_pop();
        /* skip duplicates that have already appeared */
        if (next <= S[sz - 1]) continue;

        if (sz >= S_cap) S_grow();
        S[sz++] = next;

        /* produce new candidates combining 'next' with all previous elements */
        for (size_t i = 0; i < sz - 1; ++i) {
            seq_t x = S[i];
            seq_t cand;
            if (sizeof(seq_t) <= 8) {
                unsigned __int128 prod = (unsigned __int128)(uint64_t)x *
                                        (unsigned __int128)(uint64_t)next + 1;
                if (prod > (unsigned __int128)seq_t_max) continue;
                cand = (seq_t)prod;
            } else {
                cand = x * next + (seq_t)1;
            }
            if (!is_prime_big(cand)) continue;
            heap_push(cand);
        }
    }
    return S[n - 1];
}
